from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')' and stack and stack[-1] == '(':
                stack.pop()
            else:
                return False
        return len(stack) == 0

    result = []
    current_group = ""
    for char in paren_string:
        if char == '(':
            if current_group:
                result.append(current_group)
            current_group = "("
        elif char == ')':
            current_group += ")"
            if is_balanced(current_group):
                result.append(current_group)
                current_group = ""

    return result

