def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces in the input string
    groups = []  # Initialize list to store separated groups
    stack = []  # Initialize stack to keep track of open parentheses

    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                groups.append(paren_string[start:i+1])  # Step 2 & 3: Identify and add balanced groups to the list

    return groups  # Step 4: Return the list of separated groups

